                )
            )*
        )
    )?
    $
    """,
    re.VERBOSE,
)

_COMPARATOR_RE = re.compile(
    r"""
    ^
    (?P<op>>=|<=|>|<|=|\^|~)?
    (?P<ver>
        0|[1-9]\d*
        \.
        0|[1-9]\d*
        \.
