                )
            )*
        )?
    )
    $
    """,
    re.VERBOSE,
)


def _parse_version(text):
    m = _VERSION_RE.match(text)
    if not m:
        raise ValueError(f"invalid version: {text!r}")

    major = int(m.group("major"))
    minor = int(m.group("minor"))
    patch = int(m.group("patch"))

    pre_text = m.group("pre")
    if pre_text is None:
        prerelease = None
    else:
        prerelease = tuple(pre_text.split("."))

    return (major, minor, patch, prerelease)


def _identifier_type(identifier):
    if identifier.isdigit():
        return ("num", int(identifier))
    return ("alnum", identifier)


def _compare_prerelease(a, b):
    if a is None and b is None:
        return 0
    if a is None:
        return 1
    if b is None:
        return -1

    for x, y in zip(a, b):
        tx = _identifier_type(x)
        ty = _identifier_type(y)

        if tx[0] == "num" and ty[0] == "num":
            if tx[1] < ty[1]:
