        elif tx[0] == "num":
            return -1
        elif ty[0] == "num":
            return 1
        else:
            if tx[1] < ty[1]:
                return -1
            if tx[1] > ty[1]:
                return 1

    if len(a) < len(b):
        return -1
    if len(a) > len(b):
        return 1
    return 0


def _compare_versions(a, b):
    for i in range(3):
        if a[i] < b[i]:
            return -1
        if a[i] > b[i]:
            return 1
    return _compare_prerelease(a[3], b[3])


def _parse_comparator(text):
    m = _COMPARATOR_RE.match(text)
    if not m:
        raise ValueError(f"invalid comparator: {text!r}")

    op = m.group("op") or "="
    version = _parse_version(m.group("ver"))
    return op, version


def _caret_upper_bound(v):
    major, minor, patch, _ = v

    if major > 0:
        return (major + 1, 0, 0, None)
    if minor > 0:
        return (0, minor + 1, 0, None)
    return (0, 0, patch + 1, None)


def _tilde_upper_bound(v):
    major, minor, patch, _ = v
    return (major, minor + 1, 0, None)


def _comparator_satisfied(version, comparator):
